"""Авторский банк вопросов с выбором (оригинальные формулировки). Загружается в БД (task_items) при сидировании.
Сложность b — экспертная начальная оценка; затем уточняется по статистике ответов (task_items.correct_rate)."""
from __future__ import annotations


def _q(id_, lang, grade, topic, statement, correct, wrongs, explanation, b):
    opts = ([correct] if isinstance(correct, str) else list(correct)) + list(wrongs)
    return {"id": id_, "language": lang, "grade": grade, "topic": topic, "statement": statement, "options": opts,
            "correct": correct, "explanation": explanation, "difficulty": b}


